"""
       Implementation 2 for the divide-and-conquer algorithm
       Complexity: O(log n)
       :param L: List-object
       :param e: Element to look for
       :return: Boolean value if element has been found
       """
def bisection_search2(L: Any, e: Any) -> object {
    def helper(L: Any, e: Any, low: Any, high: Any) -> object {
        if (high == low) {
            return (L[low] == e);
        }
        mid = (low + high) // 2;
        if (L[mid] == e) {
            return True;
        } elif (L[mid] > e) {
            if (low == mid) {
                return False;
            } else {
                return helper(L, e, low, (mid - 1));
            }
        } else {
            return helper(L, e, (mid + 1), high);
        }
    }
    if (len(L) == 0) {
        return False;
    } else {
        return helper(L, e, 0, (len(L) - 1));
    }
}

